.d-orbitgallery{position:relative;top:4px;color:#f1f1f1;font:400 16px/1.5 Inter,system-ui,sans-serif;font-variant-numeric:tabular-nums}.d-orbitgallery *{box-sizing:border-box}.d-orbitgallery p,.d-orbitgallery h2,.d-orbitgallery h3{margin:0}.d-orbitgallery-heading{position:absolute;inset:0 0 auto;height:26px;display:flex;align-items:center;justify-content:space-between;gap:10px;color:#a0a0a0;font-size:max(16px,calc(11.75px/var(--fit-scale,1)))}.d-orbitgallery-heading output{color:#f1f1f1;white-space:nowrap}.d-orbitgallery-field{position:absolute;left:0;right:0;top:32px;bottom:0}.d-orbitgallery-plane{position:absolute;inset:0}.d-orbitgallery-viewport{position:absolute;inset:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:none;overscroll-behavior:contain;touch-action:pan-y;outline:none}.d-orbitgallery-viewport::-webkit-scrollbar{display:none}.d-orbitgallery-viewport:focus-visible{outline:2px solid var(--focus-ring);outline-offset:-3px}.d-orbitgallery-track{position:relative;height:1900px}.d-orbitgallery-pin{position:sticky;top:0;height:var(--view-height,368px);overflow:hidden}.d-orbitgallery-photo{position:absolute;inset:0;display:block;width:100%;height:100%;max-width:none;object-fit:cover;pointer-events:none;user-select:none}.d-orbitgallery-photo-border{position:absolute;inset:0;border:1px solid rgba(255,255,255,.08);border-radius:inherit;pointer-events:none}.d-orbitgallery-status{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;font-size:14px}.d-orbitgallery-native-quote,.d-orbitgallery-filmstrip,.d-orbitgallery-native-route,.d-orbitgallery-native-document{display:none}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-heading{display:none}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-field{top:0}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-status{display:none}.d-orbitgallery{top:0}.d-orbitgallery-heading{left:24px;right:24px;top:8px}.d-orbitgallery-field{top:40px;bottom:72px;left:24px;right:24px;overflow:hidden}.d-orbitgallery-card{position:absolute;left:50%;top:20px;width:140px;height:188px;border-radius:10px;overflow:hidden;background:#0b0b0b;transform-origin:50% 50%}.d-orbitgallery-project-copy{position:absolute;left:12px;right:12px;bottom:12px;text-shadow:0 1px 5px #000}.d-orbitgallery-project-copy span,.d-orbitgallery-project-copy p{font-size:12px;line-height:1.3}.d-orbitgallery-project-copy h3{font-size:21px;font-weight:500;line-height:1.12;margin:6px 0}.d-orbitgallery-project-title{position:absolute;left:16px;right:16px;bottom:10px;font-size:16px;text-align:center;color:#a0a0a0}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-field{inset:0}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-plane{inset:auto;left:50%;top:0;width:372px;height:264px;transform:translateX(-50%) scale(var(--native-scale,1));transform-origin:50% 0}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-viewport{height:206px;bottom:auto}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-card{left:calc(186px - var(--orbit-base)/2);top:calc(50px - var(--orbit-base)/2);width:var(--orbit-base);height:var(--orbit-base)}.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-project-copy,.d-orbitgallery[data-mode="thumb"] .d-orbitgallery-project-title{display:none}@media(prefers-reduced-motion:reduce){.d-orbitgallery *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"]{color:#171717;--focus-ring:#b04a0b}
.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"] :is(button,input,[tabindex]):focus-visible{outline-color:#b04a0b}
.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"] .d-orbitgallery-heading,.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"] .d-orbitgallery-project-title{color:#626262}
.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"] .d-orbitgallery-heading output{color:#171717}
.stage[data-stage-theme="light"] .d-orbitgallery[data-mode="full"] .d-orbitgallery-project-copy{color:#f1f1f1}
